#!/usr/bin/env python3
"""Compact review of full-bank selections, with source-frame vector overlays."""
import argparse,json
from pathlib import Path

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('models',type=Path);p.add_argument('output',type=Path);p.add_argument('--semantic-bank',type=Path);p.add_argument('--bank',type=Path);p.add_argument('--study-id',default='local-croppers-2026-11-08');a=p.parse_args();a.output.mkdir(exist_ok=False);rows=[]
 for file in sorted((a.bank or a.models/'focalnet-bank').glob('*.json')):
  r=json.loads(file.read_text())
  if 'tasks' not in r:continue
  tasks={}
  for t in r['tasks']:
   modes={}
   for s in t['selected']:
    modes[s['mode']]={name:(None if s[key] is None else {'index':s[key],**t['candidates'][s[key]],'minimal_fallback':s.get('minimal_fallback',False)}) for name,key in [('raw','raw_candidate'),('guarded','detected_head_guarded_candidate')]}
   tasks[t['ratio']]=modes
  semantic=None
  if a.semantic_bank and (a.semantic_bank/(r['id']+'.json')).exists():
   sr=json.loads((a.semantic_bank/(r['id']+'.json')).read_text());st={}
   for task in sr['tasks']:
    st[task['ratio']]={}
    for selection in task['selected']:
     j=selection['detected_head_guarded_candidate'];st[task['ratio']][selection['mode']]={'guarded':None if j is None else {'index':j,**task['candidates'][j],'minimal_fallback':selection['minimal_fallback']}}
   semantic={'regions':sr['semantic_regions'],'tasks':st}
  frame=a.models/'framelite-probe'/(r['id']+'.json');rows.append({k:r[k] for k in ['id','family_id','use','width','height','heads']}|{'tasks':tasks,'semantic':semantic,'frame':json.loads(frame.read_text())['bbox_normalized'] if frame.exists() else None,'image':'http://dev.lan:3300/zensally/runtime-models/2026-11-08/gallery/assets/'+r['id']+'.png'})
 html='''<!doctype html><meta charset="utf-8"><title>Photographic crop review</title><style>body{font:15px system-ui;background:#202329;color:#eee;margin:20px}h1{font-size:25px}p{max-width:1150px;line-height:1.45}nav{position:sticky;top:0;z-index:3;background:#202329;padding:10px 0;display:flex;flex-wrap:wrap;gap:14px}select,button{font:inherit;padding:5px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px}article{background:#303640;padding:12px}h2{font-size:16px;margin:0 0 8px}.views{display:grid;grid-template-columns:1fr 1fr;gap:8px}.views svg{width:100%;height:300px;background:#171a20}.note{min-height:44px;font-size:13px;line-height:1.4}button[data-choice]{margin:4px 4px 0 0}.chosen{outline:3px solid #87cefa}small{color:#c9ced5}</style><h1>Photographic crop review</h1><p>56 synthetic sources, eleven requested ratios, two crop amounts. Left: original with selected crop in green and detected heads in pink. Right: the crop, or the full image contained in the requested frame when the candidate bank has no head-preserving option. Detected heads are incomplete protection; no source has certified full face coverage. Products and brand text are unprotected by the base model. Optional conservative product/story regions cover eight witnesses; they are unreviewed model annotations, not certified labels.</p><nav><label>Ratio <select id="ratio"></select></label><label>Amount <select id="mode"><option value="maximal">More cropping</option><option value="minimal">Least cropping</option></select></label><label><input id="guard" type="checkbox" checked>Preserve detected heads</label><label><input id="semantic" type="checkbox">Protect annotated product/story (8 scenes)</label><label><input id="frame" type="checkbox">Show FrameLite's free-ratio crop in blue</label><button id="export">Export my ratings</button><span id="count"></span></nav><main></main><script>
const studyId=STUDY_ID,storageKey='zensally-local-crops-v1'+(studyId==='local-croppers-2026-11-08'?'':':'+studyId);const data=DATA,ratios=['1:1','4:3','3:4','16:9','9:16','2:1','1:2','3:1','1:3','6:1','1:6'];let ratings=JSON.parse(localStorage.getItem(storageKey)||'{}');const ratio=document.querySelector('#ratio'),mode=document.querySelector('#mode'),guard=document.querySelector('#guard');for(const r of ratios){const o=document.createElement('option');o.value=r;o.textContent=r;ratio.append(o)}ratio.value='3:1';
function selection(row){if(document.querySelector('#semantic').checked&&row.semantic)return row.semantic.tasks[ratio.value][mode.value].guarded;return row.tasks[ratio.value][mode.value][guard.checked?'guarded':'raw']}
function key(row){return[row.id,ratio.value,mode.value,guard.checked?'guarded':'raw'].join('|')+(document.querySelector('#semantic').checked&&row.semantic?'|semantic-v1':'')}
function svg(row,box,original){let n=document.createElementNS('http://www.w3.org/2000/svg','svg');const w=row.width,h=row.height;const b=box||[0,0,1,1];n.setAttribute('viewBox',original?'0 0 '+w+' '+h:[b[0]*w,b[1]*h,(b[2]-b[0])*w,(b[3]-b[1])*h].join(' '));n.setAttribute('preserveAspectRatio','xMidYMid meet');if(!original){const[x,y]=ratio.value.split(':').map(Number);n.style.height='auto';n.style.aspectRatio=x/y;n.style.maxHeight='360px'}let im=document.createElementNS(n.namespaceURI,'image');im.setAttribute('href',row.image);im.setAttribute('width',w);im.setAttribute('height',h);n.append(im);function rect(b,color){let el=document.createElementNS(n.namespaceURI,'rect');for(const[k,v]of Object.entries({x:b[0]*w,y:b[1]*h,width:(b[2]-b[0])*w,height:(b[3]-b[1])*h,fill:'none',stroke:color,'stroke-width':Math.max(w,h)/150}))el.setAttribute(k,v);n.append(el)}if(original){if(box)rect(box,'#70ff90');for(const head of row.heads)rect(head,'#ff73ce');if(document.querySelector('#semantic').checked&&row.semantic)for(const region of row.semantic.regions)rect(region.box_percent.map(v=>v/100),'#ffdc60');if(document.querySelector('#frame').checked&&row.frame)rect(row.frame,'#55b9ff')}return n}
function render(){const main=document.querySelector('main');main.innerHTML='';for(const row of data){const s=selection(row),card=document.createElement('article'),title=document.createElement('h2');title.textContent=row.id;card.append(title);const v=document.createElement('div');v.className='views';v.append(svg(row,s?.box,true),svg(row,s?.box,false));card.append(v);const note=document.createElement('p');note.className='note';note.textContent=s?(s.minimal_fallback?'Least-crop fallback · ':'Crop · ')+'retained importance '+s.retained_importance.toFixed(3)+' · detected heads '+(s.contains_detected_heads?'retained':'cut'):document.querySelector('#semantic').checked&&row.semantic?'Contain · whole product/story and heads do not fit':'Contain · no candidate preserves all detected heads at this crop amount';card.append(note);const buttons=document.createElement('div');for(const choice of ['Good','Bad','Uncertain']){const b=document.createElement('button');b.dataset.choice=choice;b.textContent=choice;if(ratings[key(row)]?.rating===choice)b.className='chosen';b.onclick=()=>{ratings[key(row)]={study:studyId,source_id:row.id,family_id:row.family_id,source_role:row.use,ratio:ratio.value,mode:mode.value,detected_head_guard:guard.checked||(document.querySelector('#semantic').checked&&!!row.semantic),semantic_region_profile:document.querySelector('#semantic').checked&&!!row.semantic,rating:choice,bbox:s?.box||null,action:s?'crop':'contain',candidate_index:s?.index??null,face_coverage_certified:false,review_origin:'browser user action; reviewer identity unverified'};localStorage.setItem(storageKey,JSON.stringify(ratings));render()};buttons.append(b)}card.append(buttons);main.append(card)}document.querySelector('#count').textContent=Object.keys(ratings).length+' rated'}
for(const el of document.querySelectorAll('select,input'))el.onchange=render;document.querySelector('#export').onclick=()=>{const b=new Blob([JSON.stringify({schema:1,study:studyId,ratings:Object.values(ratings),training_admission_automatic:false},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='zensally-crop-ratings.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};render();</script>'''
 (a.output/'index.html').write_text(html.replace('STUDY_ID',json.dumps(a.study_id)).replace('DATA',json.dumps(rows)));(a.output/'selections.json').write_text(json.dumps(rows,indent=2)+'\n');print(json.dumps({'sources':len(rows),'html_bytes':(a.output/'index.html').stat().st_size}))
if __name__=='__main__':main()
